"""Refresh review notes from actual measurements without promoting blockers."""
import csv
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def rows(path):
    with (ROOT/path).open(encoding="utf-8-sig",newline="") as f:return list(csv.DictReader(f))

def main():
    cards=ROOT/"docs/agents";cards.mkdir(exist_ok=True)
    mapping=rows("docs/source_agent_map.csv")
    descriptions={
      "directory":("Extract extension institution facts from ICAR-style HTML tables.","Four-column English directory HTML; serial/address/host/sanction-year. BeautifulSoup 4.14.3, no LLM.","Header routing; 1-based table/row locators and full row evidence. District is the explicit Distt. token; address/host text retained; sanction year integer. Crop/observation period not applicable.","Real 54-row snapshot produces 162 observations. Ten source-derived row cases; unit tests cover count, source locators and independent expected district/year pairs.","Historical typo/freshness unverified; no inferred LGD. S22 telephone PDF remains pending; no OCR/contact extraction claimed."),
      "scheme":("Extract descriptive scheme fields without interpreting legal benefits or substituting procurement statistics.","Hindi UTF-8 HTML with scheme/department context and two-cell rows. BeautifulSoup 4.14.3, no LLM.","Original Hindi label becomes variable; original value retained with row evidence. Crop not applicable; geographic/effective period unknown explicitly coded. Empty values invalid; no inferred amount/zero.","Real MSP scheme snapshot produces 23 rows, partial because cells are blank. Ten independently source-checked Hindi fragment cases; missing values and incomplete run tested.","Only S06 operational as partial. PMFBY/PM-KISAN/legal pages lack tested source-specific parsers. No general policy reasoning or crop-level entitlement validation."),
      "statistics":("Import explicitly structured numeric observations and conservatively extract supported production sentences.","CSV required six headers plus optional metadata; text-layer PDF with one explicit English production grammar. Python csv / pypdf 6.12.1; no LLM.","Preserve value string, declared unit/qualifier and origin metadata; normalize crop/location/period; physical CSV line or PDF page/character locator and evidence. Lower bounds/targets remain distinct variables.","Ten PDF-source-checked manual-transcription CSV cases, unit/period/context/1% matching tests, real PDF wheat sentence and dump restore tested. PDF yields one wheat fact; not a general PDF table extractor.","S23 partial. S11/S12 interactive queries and S13 annual tables pending. CSV evaluation measures importer, not automatic transcription. Manual source context carries rice periods; PDF parser does not infer them. No trusted LGD registry." )}
    for agent in sorted({r["agent"] for r in mapping}):
        sources=[r for r in mapping if r["agent"]==agent]
        lines=["# Agent card: "+agent,"","Status: "+("implemented and tested within the limited scope below; source coverage partial" if agent in descriptions else "pending / not implemented"),"", "Inventory sources: "+", ".join(r["source_id"]+" ("+r["status"]+")" for r in sources),""]
        if agent in descriptions:
            purpose,inputs,rules,tests,limitations=descriptions[agent]
            lines += ["## Responsibility and input","",purpose,"",inputs,"","## Extraction, normalization and provenance","",rules,"","Output: observation-v1 long-form records with source hash/type/agent/run UUID, locator, crop/location/period/variable/value/unit, validation status/errors and raw evidence. See db/dictionary.md and eval/README.md.","","## Failure handling and decisions","","Router errors yield failed status, no invented observations. Invalid rows remain for audit; partially supported PDFs and incomplete rows yield partial status. Storage is transactional; logs retain failures. All decisions are fixed code. No model inference, confidence estimate, autonomous reasoning or cooperative agent hand-off is claimed.","","## Evidence","",tests,"", "Measured per-agent benchmark results are in eval/results.json and eval/phase2_metrics.csv; the high fragment F1 is not independent unseen-document performance. Reference source verification is by the implementing agent, not a calibrated human panel.","","## Known limits","",limitations]
        else:
            lines += ["Responsibility proposed in Phase 1: "+"; ".join(r["source_name"] for r in sources)+".","","No executable source-specific parser, model, extraction output, normalization, reference trajectory, failure-recovery claim, or measured performance is supplied for this proposed agent. Data collection and source-specific format/field checks are required before implementation. Modality and source intentions remain in the preserved inventory and TA scope.","","No source is marked done. Pending cards document scope rather than operational coverage. They do not count as implemented agents for the ten-case minimum. The excluded_personal agent is an explicit out-of-scope policy marker for S17, not a processor."]
        (cards/(agent+".md")).write_text("\n".join(lines)+"\n",encoding="utf-8")
    bench=rows("evidence/tool_benchmarks.csv")
    lines=["# Technical challenge, choices and measured tool tests","","## Actual sources and stages","","The TA shortlist prioritizes e-Vikas, DES APY, IMD advisories, ICAR KVK and conditional e-Uparjan. Inspection found only inventories/documentation in the initial repo, no crop corpus or runnable agents. Six source snapshots were collected with TLS verification. Direct ICAR directory and Hindi MSP scheme tables are operational; the historical Economic Survey supports a narrow sentence extractor and a transparently manual transcription import. Fertilizer/production/advisory portal forms are not numerical result datasets. No support for all six crops or all stages is inferred from a source listing.","","## Challenges and design trade-offs","","Dynamic pages contain unrendered {{...}} tokens. Treating them as recommendations would fabricate facts; the router rejects them. DES APY's query form is saved but automated filter/result retrieval is pending. IMD advisory filtering, e-Uparjan quantitative data, scanned/Hindi PDF OCR and model reasoning remain implementation gaps, not proven research impossibilities. The e-Mandi PDF is a workflow manual, not market-price data.","","HTML tables preserve source rows more reliably for this narrow task than free-form model generation. The chosen sequential routing is inspectable on modest CPU hardware and supports unseen values within declared layouts. It lacks adaptable layout reasoning and cooperative agents. General PDF text extraction is not table extraction; the conservative sentence grammar omits unsupported facts explicitly. CSV imports preserve manual transcription provenance and never masquerade as automated PDF extraction. Missing dimensions are explicit; source spelling errors remain visible rather than guessing canonical locations.","","## Literature and open-source alternatives","","[pypdf extraction documentation](https://pypdf.readthedocs.io/en/stable/user/extract-text.html) describes text-layer extraction and the need for OCR for image-only pages. This supports using pypdf for searchable PDFs, not claiming scanned-table support. [pdfplumber project documentation](https://github.com/jsvine/pdfplumber) offers character/layout inspection and configurable table extraction. We actually tested its text extraction; table reconstruction and OCR accuracy are not measured here. BeautifulSoup handles selected HTML tables; it cannot render JavaScript or validate agricultural meaning.","","[LoRA, Hu et al.](https://arxiv.org/abs/2106.09685) freezes base weights and trains low-rank parameter updates. [QLoRA, Dettmers et al.](https://arxiv.org/abs/2305.14314) combines quantized base weights with adapter training. These are published approaches, not implemented training results in this project. No weights, adapter or separate labelled training data were supplied. The machine has approximately 16 GiB RAM and 16 logical CPUs; torch/transformers were absent in the inspected system Python. Dedicated accelerator suitability was not established. Optional local inference/scoring code is provided, but no actual base/adapter run is claimed.","","A calibrated LLM judge could evaluate semantic groundedness but needs independently human-labelled calibration (at least ten, agreement >=80%). This project has no such human panel or judge. Deterministic field and exact-trajectory comparisons are used only where semantics are explicit; M10 is unavailable. External Foundry/AgentEvals/LangSmith execution is not claimed.","","## Tools actually executed","","Command for every row: `python scripts/benchmark_tools.py`. Original numeric evidence: evidence/tool_benchmarks.csv. Each tool was run on both real downloaded project PDFs with default text extraction; full file, all pages, no OCR. Timings are one-run measurements and not comparative benchmarks across hardware.","","| Tool/version | Source | Pages | Text pages | Characters | Seconds | Status |","|---|---|---:|---:|---:|---:|---|"]
    for b in bench: lines.append(f"| {b['tool']} {b['version']} | {b['input']} | {b['pages']} | {b['text_pages']} | {b['characters']} | {float(b['seconds']):.3f} | {b['status']} |")
    lines += ["","These are real execution/coverage counts, not reference-labelled accuracy. Neither tool's character count proves correct Hindi encoding or table structure. pypdf was selected for the narrow production parser; pdfplumber remains a tested alternative rather than an installed-but-unused success claim. Numeric field F1 is reported separately on transparently source-derived CSV/HTML fragments.","","## Acquisition and provenance limitations","","The inventory ICAR URL at icar.gov.in failed with an expired certificate; the official icar.org.in/en/node/15044 alternative returned HTTP 200 without bypassing verification. CM Helpline, e-Mandi manual, Economic Survey, e-Vikas and DES APY returned HTTP 200 in actual command output. The manifest records local collection date 25 October 2026 and unknown/unverified licenses; no guessed license or publication date is assigned. No historical acquisition timestamp/log was fabricated. The reproducible fetch script records only future attempts it actually executes.","","The source PDFs/HTML are stored with hashes; survey page 7 was rendered and inspected against manual numerical references. Scheme and directory fields were checked against their original source tables. The 30 units share parent documents and were visible in development; no independent held-out generalization or instructor surprise success is asserted."]
    (ROOT/"docs/challenge.md").write_text("\n".join(lines)+"\n",encoding="utf-8")
    print("Refreshed",len({r['agent'] for r in mapping}),"agent cards and challenge note")

if __name__=="__main__":main()
